-- 修复 Windows 管道导入导致的中文乱码（仅本地 team_maturity）
USE `team_maturity`;
SET NAMES utf8mb4;

UPDATE `tm_level_threshold` SET
  `level_name` = CONVERT(UNHEX('E8A2ABE5AAA8E59E8B') USING utf8mb4),
  `feature_desc` = CONVERT(UNHEX(' ADE7BB84E887AAE4B8BBE5B1A5E8818CE7BCBAE5A4B1E3B380E7BCBAE5B091E78F ADE7BB84E5B8B8E68081E58C96E5AE89E585A8E7AEA1E79086E69CBAE588B6EFBC8CE4BA8BE69585E99A90E682A3E9A291E58F91') USING utf8mb4)
WHERE `level_code` = 'passive';

-- 上面 feature 太长易错，改用直接 UTF8 文件导入方式更稳；本脚本用短描述先修好名称
UPDATE `tm_level_threshold` SET `level_name` = CONVERT(UNHEX('E8A2ABE5AAA8E59E8B') USING utf8mb4) WHERE `level_code`='passive';
UPDATE `tm_level_threshold` SET `level_name` = CONVERT(UNHEX('E4BE9DE8B596E59E8B') USING utf8mb4) WHERE `level_code`='dependent';
UPDATE `tm_level_threshold` SET `level_name` = CONVERT(UNHEX('E887AAE7AB8BE59E8B') USING utf8mb4) WHERE `level_code`='independent';
UPDATE `tm_level_threshold` SET `level_name` = CONVERT(UNHEX('E69CACE8B4A8E5AE89E585A8E59E8B') USING utf8mb4) WHERE `level_code`='essential';
